class Solution {
    unordered_map<string, int> memo;
    const int INF = 1000000;

    string shrink(string s) {
        bool changed = true;

        while (changed) {
            changed = false;

            for (int i = 0; i < (int)s.size();) {
                int j = i;

                while (j < (int)s.size() && s[j] == s[i])
                    ++j;

                if (j - i >= 3) {
                    s.erase(i, j - i);
                    changed = true;
                    break;
                }

                i = j;
            }
        }

        return s;
    }

    int dfs(string board, vector<int>& hand) {
        board = shrink(board);

        if (board.empty())
            return 0;

        string key = board + "#";
        for (char c : string("RYBGW"))
            key += to_string(hand[c - 'A']) + ",";

        if (memo.count(key))
            return memo[key];

        int ans = INF;

        // Option 1: Complete and remove an existing group.
        for (int i = 0; i < (int)board.size();) {
            int j = i;

            while (j < (int)board.size() &&
                   board[j] == board[i])
                ++j;

            int need = 3 - (j - i);
            int idx = board[i] - 'A';

            if (need > 0 && hand[idx] >= need) {
                hand[idx] -= need;

                string next = board.substr(0, i) +
                              board.substr(j);

                int steps = dfs(next, hand);

                if (steps != INF)
                    ans = min(ans, need + steps);

                hand[idx] += need;
            }

            i = j;
        }

        // Option 2: Insert a different-colored ball
        // between two identical adjacent balls.
        for (int i = 1; i < (int)board.size(); ++i) {
            if (board[i - 1] != board[i])
                continue;

            for (char c : string("RYBGW")) {
                if (c == board[i])
                    continue;

                int idx = c - 'A';

                if (hand[idx] == 0)
                    continue;

                hand[idx]--;

                string next = board;
                next.insert(next.begin() + i, c);

                int steps = dfs(next, hand);

                if (steps != INF)
                    ans = min(ans, 1 + steps);

                hand[idx]++;
            }
        }

        return memo[key] = ans;
    }

public:
    int findMinStep(string board, string handStr) {
        memo.clear();

        vector<int> hand(26, 0);

        for (char c : handStr)
            hand[c - 'A']++;

        int ans = dfs(board, hand);

        return ans == INF ? -1 : ans;
    }
};
